import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    TorusGeometry,
    PointLight,
  } = THREE;

  const root = new Group();
  const stage = new Group();
  const subject = new Group();
  const foreground = new Group();
  const primitiveResults = [];
  const gsapTimelines = [];
  const ownedResources = [];
  let disposed = false;

  root.name = config.id || 'collection-stat-tile';
  root.add(stage);
  root.add(subject);
  root.add(foreground);

  const ink = vec3(0.007, 0.007, 0.012);
  const surface = vec3(0.043, 0.043, 0.063);
  const paper = vec3(0.91, 0.925, 0.949);
  const accent = vec3(1.0, 0.016, 0.031);

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = vec4(
    mix(ink, surface, smoothstep(0.0, 1.0, uv().y)),
    1.0,
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial,
  );
  backdrop.name = 'machined-atelier-backdrop';
  backdrop.position.z = -2.5;
  stage.add(backdrop);
  ownedResources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial();
  shadowMaterial.colorNode = vec4(vec3(0.005, 0.005, 0.008), 1.0);
  shadowMaterial.opacity = 0.48;
  shadowMaterial.transparent = true;
  shadowMaterial.depthWrite = false;

  const contactShadow = new Mesh(
    new CircleGeometry(1.55, 64),
    shadowMaterial,
  );
  contactShadow.name = 'subject-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.05, -0.12);
  contactShadow.scale.set(1.25, 0.7, 1);
  stage.add(contactShadow);
  ownedResources.push(contactShadow.geometry, contactShadow.material);

  const accentMaterial = new MeshStandardNodeMaterial();
  accentMaterial.colorNode = vec4(accent, 1.0);
  accentMaterial.metalness = 0.45;
  accentMaterial.roughness = 0.52;

  const accentRing = new Mesh(
    new TorusGeometry(1.18, 0.018, 12, 96),
    accentMaterial,
  );
  accentRing.name = 'signal-red-foreground-ring';
  accentRing.position.set(0, -0.68, 0.28);
  accentRing.rotation.x = Math.PI * 0.5;
  foreground.add(accentRing);
  ownedResources.push(accentRing.geometry, accentRing.material);

  const rimLight = new PointLight(0xff2a38, 0.78, 5.5, 2);
  rimLight.name = 'accent-rim-light';
  rimLight.position.set(-1.8, 1.4, 1.6);
  root.add(rimLight);

  const fillLight = new PointLight(0xe8ecf2, 0.42, 4.5, 2);
  fillLight.name = 'paper-fill-light';
  fillLight.position.set(1.8, -0.6, 1.2);
  root.add(fillLight);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize
        ? item.typography.fontSize * 100
        : item.role === 'label'
          ? 14
          : 28,
      color: item.role === 'label' ? '#e8ecf2' : '#ff2a38',
      align: item.typography?.align ?? 'center',
      letterSpacingPx: item.role === 'label' ? 1.2 : 0,
    });
    textObject.position.set(0, item.role === 'label' ? -0.92 : 0.92, 0.34);
    root.add(textObject);
  }

  const settleTimeline = gsap.timeline({ paused: true });
  subject.scale.set(0.96, 0.96, 0.96);
  subject.position.y = 0.4;
  settleTimeline
    .to(subject.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out',
    })
    .to(subject.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.28,
      ease: 'power2.out',
    }, '<0.32')
    .to(subject.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    });
  settleTimeline.play();
  gsapTimelines.push(settleTimeline);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      const loadedScene = gltf.scene;
      loadedScene.name = 'machined-metal-stat-subject';
      loadedScene.traverse((object) => {
        if (object.isMesh) {
          object.castShadow = true;
          object.receiveShadow = true;
        }
      });
      subject.add(loadedScene);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive?.name || !ctx.primitives?.[primitive.name]) continue;
    const result = ctx.primitives[primitive.name](
      root,
      primitive.params ?? {},
    );
    if (result) primitiveResults.push(result);
  }

  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(subject.position, {
    y: -0.15,
    duration: 0.3,
    ease: 'power2.out',
  });
  gsapTimelines.push(hoverTimeline);

  root.userData.handlers = {
    hover(event) {
      const active = event?.active ?? event?.type === 'pointerenter';
      if (active) hoverTimeline.play();
      else hoverTimeline.reverse();
    },
    click() {
      gsap.to(subject.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('hub-collection.select', {
        node: root.name,
      });
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const timeline of gsapTimelines) {
      timeline.kill();
    }

    gsap.killTweensOf(root);
    gsap.killTweensOf(subject);
    gsap.killTweensOf(subject.position);
    gsap.killTweensOf(subject.scale);

    root.traverse((object) => {
      if (!object.isMesh) return;
      object.geometry?.dispose?.();

      const material = object.material;
      const materials = Array.isArray(material) ? material : [material];
      for (const mat of materials) {
        if (!mat) continue;
        for (const key of Object.keys(mat)) {
          const value = mat[key];
          if (value?.isTexture) value.dispose?.();
        }
        mat.dispose?.();
      }
    });

    for (const resource of ownedResources) {
      resource?.dispose?.();
    }
  };

  return root;
}
